<?php require dirname(__DIR__).'/config/bootstrap.php';$err='';if($_SERVER['REQUEST_METHOD']==='POST'){Security::verify();$key='login_'.sha1($_SERVER['REMOTE_ADDR']??'');$_SESSION[$key]??=0;if($_SESSION[$key]>=8){http_response_code(429);$err='Too many attempts. Try later.';}elseif(Auth::login($_POST['email']??'',$_POST['password']??'')){unset($_SESSION[$key]);redirect('/account/');}else{$_SESSION[$key]++;$err='Invalid email or password';}}?><!doctype html><html><head><meta charset="utf-8"><link rel="stylesheet" href="/assets/css/store.css"></head><body><main class="panel narrow"><h1>Login</h1><p class="error"><?=e($err)?></p><form method="post"><?=Security::field()?><label>Email<input type="email" name="email" required></label><label>Password<input type="password" name="password" required></label><button>Login</button></form><a href="/auth/register.php">Create account</a></main></body></html>